/// Spawns the Fa CLI as a subprocess with a PTY, feeds output to an xterm
/// terminal emulator, and provides keystroke sending + output capture.
final class FaCliHarness {
  FaCliHarness._(
    this.pty,
    this.terminal,
    this.columns,
    this.rows,
    this._ownedCwd,
